export function evaluate({ inputs, time }) {
  const v0 = Number(inputs.launchSpeed);
  const g = 9.8;
  const apexTime = v0 / g;
  const apexHeight = (v0 * v0) / (2 * g);
  const t = Math.min(Math.max(0, Number(time)), 2 * apexTime);
  const velocity = v0 - g * t;
  const height = Math.max(0, v0 * t - 0.5 * g * t * t);

  let motionStateStr = "Moving up";
  if (Math.abs(velocity) < 0.05 || Math.abs(t - apexTime) < 0.01) {
    motionStateStr = "Still for an instant";
  } else if (velocity < 0) {
    motionStateStr = "Moving down";
  }
  const gravityStateStr = "Gravity pulls down";

  const originX = 240;
  const originY = 340;
  const scaleY = 180;

  const ballX = originX;
  const ballY = originY - height * scaleY;

  const objects = [];

  objects.push({
    kind: "line",
    id: "launch_guide",
    from: { x: originX - 40, y: originY },
    to: { x: originX + 40, y: originY },
    role: "neutral"
  });
  objects.push(sdk.text("launch_guide_label", originX + 45, originY + 4, "Launch height", { align: "start", role: "neutral" }));

  const axisObj = sdk.axis("height_axis", {
    x: originX - 60,
    y: originY,
    length: 280,
    orientation: "y",
    min: 0,
    max: 1.5,
    ticks: [0, 0.5, 1.0, 1.5],
    label: "Height",
    unit: "m",
    role: "neutral"
  });
  objects.push(axisObj);

  const ballObj = sdk.circle("ball.toss", ballX, ballY, 28, { role: "learner" });
  objects.push(ballObj);

  const vecV = sdk.vector("vec.v", { x: ballX - 24, y: ballY }, {
    value: velocity,
    direction: "up",
    scale: 25,
    label: "v",
    role: "learner"
  });
  objects.push(...vecV);

  const vecA = sdk.vector("vec.a", { x: ballX + 24, y: ballY }, {
    value: -g,
    direction: "up",
    scale: 4,
    label: "a",
    role: "warning"
  });
  objects.push(...vecA);

  const calloutObj = sdk.callout(ballX + 40, ballY - 10, [
    motionStateStr,
    gravityStateStr
  ], { id: "callout.toss", role: "tutor" });
  objects.push(...calloutObj);

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "motionState", value: motionStateStr },
        { id: "gravityState", value: gravityStateStr }
      ]
    },
    quantities: {
      launchSpeed: v0,
      gravity: g,
      apexTime,
      apexHeight,
      velocity,
      height
    }
  };
}
